            "ae.cannotMove": "Verschieben nicht möglich: {0}",
            "guide.curvesRamps": "<b>Speed Ramps:</b> die Presets von slowMid bis hitOut sind für Time Remapping gedacht. Schalte es auf einer Ebene ein (Ebene &gt; Zeit &gt; Zeitverzerrung aktivieren), wähle beide Keyframes und drücke Anwenden. Lies die Kurve als Geschwindigkeitsprofil: ihre Steigung ist die Abspielrate, eine flache Mitte ist also Zeitlupe und steile Enden sind die schnellen Teile daneben. Keine davon überschwingt, denn bei Time Remap hieße das, über das Ende des Materials hinaus zu lesen.",
            "guide.curvesMatched": "<b>Wo du gerade stehst:</b> das Preset, auf dem der Editor gerade sitzt, leuchtet in der Bibliothek auf - egal ob du es angeklickt, die Werte eingetippt oder die Anfasser daraufgezogen hast. Der Abgleich ist exakt, und der Editor arbeitet in Hundertsteln, also genau der Genauigkeit, die die vier Felder zeigen. Die Zahl im Feld ist damit wirklich die gespeicherte Zahl. Die Kurve, auf der du das Panel verlässt, wird gemerkt und kommt beim nächsten Öffnen zurück.",
            "guide.mainColor": "<b>Farbe:</b> das Feld neben Solid öffnet einen Picker mit Hex-Feld, zuletzt benutzten Farben und einer Pipette. Die Pipette nimmt überall auf dem Bildschirm auf, nicht nur innerhalb des Panels - unter Windows wartet ein Hilfsprozess auf deinen nächsten Klick, gib ihm also einen Moment, bis die Schaltfläche zu pulsieren beginnt, und klicke erst dann; unter macOS öffnet sich das Farbfenster des Systems, dessen Lupe dasselbe leistet. Diese Farbe verwendet auch das Shortcut-Skript für farbige Flächen.",
            "guide.troubleSize": "<b>Das Panel öffnet in einer seltsamen Breite:</b> sobald ein Panel einmal angedockt war, merkt sich After Effects seine Größe im Arbeitsbereich und ignoriert, was die Erweiterung verlangt. Von der Erweiterung aus lässt sich daran nichts ändern. Stelle es ein wie gewünscht, dann Fenster &gt; Arbeitsbereich &gt; Änderungen an diesem Arbeitsbereich speichern, und beende After Effects über Datei &gt; Beenden, damit die Einstellungen geschrieben werden. Ein späterer Wechsel zurück zu diesem Arbeitsbereich stellt das Layout wieder her. Das Panel selbst ist für jede Breite gebaut, auch für ein schmales Dock.",
            "main.transformValues": "Transformationswerte",
            "main.tfAnchor": "Anker",
            "main.tfPosition": "Position",
            "main.tfScale": "Skalierung",
            "main.tfRotation": "Drehung",
            "main.tfOpacity": "Deckkraft",
            "main.transformAbout": "Ziehe einen Wert seitwärts, um ihn zu scrubben, oder klicke ihn an, um zu tippen. Shift vergröbert das Ziehen, Strg verfeinert es. Die Zeilen folgen der Auswahl von selbst, und geschrieben wird nur der Wert, den du änderst - der Rest der Ebene bleibt auch bei mehreren ausgewählten Ebenen unangetastet. Die Kette hält die Skalierung proportional. Eine Eigenschaft mit Keyframes wird so geschrieben wie in der Timeline: auf einem Keyframe wird dieser aktualisiert, dazwischen entsteht ein neuer. Abgeblendet ist nur eine Zeile mit Expression, da diese den Wert bestimmt. Eine 3D-Ebene behält ihr Z.",
            "main.shapes": "Formebenen",
            "main.shapeFill": "Fläche",
            "main.shapeStroke": "Kontur",
            "main.shapeWidth": "Breite",
            "main.shapesAbout": "Die Zeilen zeigen, was die ausgewählte Formgruppe tatsächlich trägt - welche Gruppe das ist, entscheidet deine Auswahl in der Timeline. Wähle eine Farbe oder ziehe einen Wert, und es greift sofort; geschrieben wird nur, was du anfasst, und eine Eigenschaft mit Keyframes bekommt einen Keyframe wie in der Timeline. Zeilen, die die Form nicht hat, werden ausgeblendet: eine Ellipse hat keine Rundung.",
            "msg.transformRead": "Von '{0}' gelesen",
            "msg.nothingToApply": "Mindestens einen Wert eintragen",
