            "ae.exprAdded": "Expression auf {0} Ebenen hinzugefügt",
            "ae.exprRemoved": "Expression von {0} Ebenen entfernt",
            "guide.rowModifiers": "<b>Modifikatortasten auf den Zeilen:</b> Shift beim Ziehen eines Werts vergröbert den Schritt um das Zehnfache, Strg verfeinert ihn. Alt-Klick auf eine Stoppuhr fügt eine Expression hinzu oder entfernt sie, statt die Animation zu schalten - derselbe Reflex wie in der Timeline. Die Arbeit übernimmt After Effects selbst über Animation &gt; Expression hinzufügen, sodass die Expression-Zeile tippbereit aufgeht und der Text die Eigenreferenz der Eigenschaft ist, genau wie nach einem Alt-Klick in der Timeline.",
