            "ae.orgEmptyRemoved": "Carpetas vacías eliminadas: {0}",
            "ae.cannotMove": "No se puede mover: {0}",
            "guide.curvesRamps": "<b>Rampas de velocidad:</b> los ajustes de slowMid a hitOut están pensados para el Time Remapping. Actívalo en una capa (Capa &gt; Tiempo &gt; Habilitar reasignación de tiempo), selecciona ambos fotogramas clave y pulsa Aplicar. Lee la curva como un perfil de velocidad: su pendiente es la velocidad de reproducción, así que un centro plano es cámara lenta y los extremos empinados son las partes rápidas a cada lado. Ninguna rebota, porque en Time Remap eso significaría leer más allá del final del metraje.",
            "guide.curvesMatched": "<b>Dónde estás:</b> el ajuste sobre el que está el editor se ilumina en la biblioteca, tanto si lo has pulsado como si has escrito los valores o has arrastrado los tiradores hasta él. La coincidencia es exacta y el editor trabaja en centésimas, la misma precisión que muestran los cuatro campos, así que el número del campo es realmente el que se guarda. La curva en la que dejas el panel se recuerda y vuelve al abrirlo de nuevo.",
            "guide.mainColor": "<b>Color:</b> la muestra junto a Sólido abre un selector con campo hex, colores recientes y un cuentagotas. El cuentagotas toma color de cualquier punto de la pantalla, no solo dentro del panel: en Windows un proceso auxiliar espera tu siguiente clic, así que dale un momento hasta que el botón empiece a parpadear y pulsa entonces; en macOS abre el panel de color del sistema, cuya lupa hace lo mismo. Este color lo usa también el script de atajo para el sólido de color.",
            "guide.troubleSize": "<b>El panel se abre con un ancho extraño:</b> una vez que un panel ha sido acoplado, After Effects recuerda su tamaño en el espacio de trabajo e ignora lo que pide la extensión. Desde la extensión no hay forma de evitarlo. Ajústalo como quieras, luego Ventana &gt; Espacio de trabajo &gt; Guardar cambios en este espacio de trabajo, y cierra After Effects con Archivo &gt; Salir para que se escriban las preferencias. Volver más tarde a ese espacio de trabajo restaura la disposición. El panel está hecho para funcionar a cualquier ancho, incluso en un acople estrecho.",
            "main.transformValues": "Valores de transformación",
            "main.tfAnchor": "Anclaje",
            "main.tfPosition": "Posición",
            "main.tfScale": "Escala",
            "main.tfRotation": "Rotación",
            "main.tfOpacity": "Opacidad",
            "main.transformAbout": "Arrastra un valor de lado para ajustarlo, o haz clic para escribirlo. Mayús hace el arrastre más grueso, Ctrl más fino. Las filas siguen a la selección por sí solas y solo se escribe el valor que cambias, así que el resto de la capa se queda igual incluso con varias capas seleccionadas. La cadena mantiene la escala proporcional. Una propiedad con fotogramas clave se escribe como en la línea de tiempo: sobre un fotograma clave lo actualiza, entre ellos crea uno nuevo. Solo se atenúa una fila con expresión, porque es la expresión quien decide el valor. Una capa 3D conserva su Z.",
            "main.shapes": "Capas de forma",
            "main.shapeFill": "Relleno",
            "main.shapeStroke": "Trazo",
            "main.shapeWidth": "Grosor",
            "main.shapesAbout": "Las filas muestran lo que lleva realmente el grupo de forma seleccionado, y qué grupo es lo decide lo que tengas seleccionado en la línea de tiempo. Elige un color o arrastra un valor y se aplica al momento; solo se escribe lo que tocas, y una propiedad con fotogramas clave recibe uno igual que en la línea de tiempo. Las filas que la forma no tiene se ocultan: una elipse no tiene redondez.",
            "msg.transformRead": "Leído de '{0}'",
