            "guide.rowModifiers": "<b>Teclas modificadoras en las filas:</b> Mayús al arrastrar un valor multiplica el paso por diez, Ctrl lo afina. Alt+clic en un cronómetro añade o quita una expresión en vez de activar la animación, el mismo reflejo que en la línea de tiempo. El trabajo lo hace el propio After Effects mediante Animación &gt; Añadir expresión, así que la fila de la expresión se abre lista para escribir y el texto es la referencia propia de la propiedad, igual que tras un Alt+clic en la línea de tiempo.",
