            "dlg.presetNameDefault": "Moje ustawienie",
            "dlg.restoreDefaultsConfirm": "Przywrócić cały panel do stanu początkowego? Usunie to wszystkie biblioteki ustawień, które utworzyłeś lub zaimportowałeś, folder z ustawieniami efektów wraz z ulubionymi oraz rozmiar edytora.",
