            "ae.orgAssets": "Assets: {0}",
            "ae.orgEmptyRemoved": "Usunięto pustych folderów: {0}",
            "ae.cannotMove": "Nie można przenieść: {0}",
            "guide.curvesRamps": "<b>Speed rampy:</b> ustawienia od slowMid do hitOut są przeznaczone do Time Remappingu. Włącz go na warstwie (Layer &gt; Time &gt; Enable Time Remapping), zaznacz obie klatki kluczowe i naciśnij Zastosuj. Krzywą czytaj jako profil prędkości: jej nachylenie to tempo odtwarzania, więc płaski środek to zwolnienie, a strome końce to szybkie fragmenty po bokach. Żadna z nich nie przestrzeliwuje, bo przy time remapie oznaczałoby to czytanie poza końcem materiału.",
            "guide.curvesMatched": "<b>Gdzie właśnie jesteś:</b> ustawienie, na którym stoi edytor, podświetla się w bibliotece — niezależnie od tego, czy je kliknąłeś, wpisałeś wartości, czy dociągnąłeś do niego uchwyty. Dopasowanie jest dokładne, a edytor pracuje w setnych, czyli w tej samej precyzji, którą pokazują cztery pola. Liczba w polu jest więc naprawdę tą zapisaną. Krzywa, na której zostawisz panel, jest zapamiętywana i wraca po ponownym otwarciu.",
            "guide.mainColor": "<b>Kolor:</b> próbka obok Solidu otwiera picker z polem hex, ostatnimi kolorami i pipetą. Pipeta pobiera kolor z dowolnego miejsca na ekranie, nie tylko z wnętrza panelu — na Windows proces pomocniczy czeka na Twoje następne kliknięcie, więc daj mu chwilę, aż przycisk zacznie pulsować, i dopiero wtedy kliknij; na macOS otwiera się systemowy panel kolorów, którego lupa robi to samo. Tego koloru używa też skrypt skrótu dla kolorowego solidu.",
            "guide.troubleSize": "<b>Panel otwiera się w dziwnej szerokości:</b> gdy panel raz zostanie zadokowany, After Effects zapamiętuje jego rozmiar w obszarze roboczym i ignoruje to, o co prosi rozszerzenie. Z poziomu rozszerzenia nic się z tym nie da zrobić. Ustaw go, jak chcesz, potem Window &gt; Workspace &gt; Save Changes to This Workspace i zamknij After Effects przez File &gt; Exit, żeby preferencje zostały zapisane. Późniejsze przełączenie z powrotem na ten obszar roboczy przywróci układ. Sam panel jest zrobiony tak, by działać przy dowolnej szerokości, także w wąskim doku.",
            "main.transformValues": "Wartości przekształcenia",
            "main.tfAnchor": "Kotwica",
            "main.tfPosition": "Pozycja",
            "main.tfScale": "Skala",
            "main.tfRotation": "Obrót",
            "main.tfOpacity": "Krycie",
            "main.transformAbout": "Przeciągnij wartość na boki, aby ją zmieniać, albo kliknij, żeby ją wpisać. Shift zgrubia przeciąganie, Ctrl je wysubtelnia. Wiersze same podążają za zaznaczeniem i zapisywana jest tylko ta wartość, którą zmienisz, więc reszta warstwy zostaje nietknięta nawet przy kilku zaznaczonych warstwach. Łańcuszek utrzymuje proporcje skali. Właściwość z klatkami kluczowymi zapisuje się tak jak na osi czasu: na klatce ją nadpisze, pomiędzy klatkami utworzy nową. Wyszarzony jest tylko wiersz z wyrażeniem, bo to ono decyduje o wartości. Warstwa 3D zachowuje swoje Z.",
            "main.shapes": "Warstwy kształtu",
            "main.shapeFill": "Wypełnienie",
            "main.shapeStroke": "Obrys",
            "main.shapeWidth": "Szerokość",
            "main.shapesAbout": "Wiersze pokazują, co naprawdę ma zaznaczona grupa kształtu — a którą grupę, o tym decyduje zaznaczenie na osi czasu. Wybierz kolor albo przeciągnij wartość, a zadziała od razu; zapisywane jest tylko to, czego dotkniesz, a właściwość z klatkami kluczowymi dostaje klatkę tak jak na osi czasu. Wiersze, których kształt nie ma, są ukryte: elipsa nie ma zaokrąglenia.",
            "msg.transformRead": "Wczytano z '{0}'",
            "msg.nothingToApply": "Wypełnij co najmniej jedną wartość",
            "ae.invalidValue": "Niepoprawna wartość",
            "ae.nothingToApply": "Nie ma czego zastosować",
            "ae.noShapeSelected": "Wśród zaznaczonych nie ma warstwy kształtu",
            "ae.noShapeStyleFound": "Na tych warstwach nie znaleziono wypełnienia ani obrysu",
            "ae.shapeStyleApplied": "Styl zastosowany do {0} warstw kształtu",
            "ae.transformAppliedTo": "Przekształcenie zastosowane do {0} warstw",
            "ae.transformReadFail": "Nie udało się wczytać przekształcenia",
            "tip.scaleLink": "Zachowaj proporcje skali",
            "main.resetTransform": "Resetuj",
            "tip.resetTransform": "Zresetuj przekształcenie zaznaczonych warstw",
            "tip.stopwatch": "Włącz lub wyłącz animację (usuwa wszystkie klatki kluczowe). Alt+klik dodaje lub usuwa wyrażenie",
            "tip.prevKey": "Przejdź do poprzedniej klatki kluczowej",
            "tip.nextKey": "Przejdź do następnej klatki kluczowej",
            "ae.stopwatchOn": "Animacja włączona na {0} warstwach",
            "ae.stopwatchOff": "Animacja wyłączona na {0} warstwach",
            "ae.noKeysOnProp": "Ta właściwość nie ma klatek kluczowych",
