            "ae.transformReset": "Przekształcenie zresetowane na {0} warstwach",
            "tip.keyHere": "Dodaj lub usuń klatkę kluczową w bieżącym czasie",
            "ae.notAnimated": "Najpierw włącz stoper",
            "ae.keyAdded": "Klatka kluczowa dodana na {0} warstwach",
