            "ae.exprAdded": "Wyrażenie dodane na {0} warstwach",
            "ae.exprRemoved": "Wyrażenie usunięte z {0} warstw",
            "guide.rowModifiers": "<b>Klawisze modyfikujące w wierszach:</b> Shift przy przeciąganiu wartości zgrubia krok dziesięciokrotnie, Ctrl go wysubtelnia. Alt+klik na stoperze dodaje lub usuwa wyrażenie zamiast włączać animację — ten sam odruch co na osi czasu. Robotę przejmuje samo After Effects przez Animation &gt; Add Expression, więc wiersz wyrażenia otwiera się gotowy do pisania, a tekstem jest własna referencja właściwości, dokładnie jak po Alt+kliku na osi czasu.",
            "sh.tNone": "Brak",
