            "ae.cannotMove": "Déplacement impossible : {0}",
            "guide.curvesRamps": "<b>Rampes de vitesse :</b> les préconfigurations de slowMid à hitOut sont prévues pour le Time Remapping. Activez-le sur un calque (Calque &gt; Temps &gt; Activer le remappage temporel), sélectionnez les deux images clés et appuyez sur Appliquer. Lisez la courbe comme un profil de vitesse : sa pente est la cadence de lecture, un milieu plat est donc du ralenti et des extrémités raides sont les parties rapides de part et d'autre. Aucune ne dépasse, car sur le Time Remap cela reviendrait à lire au-delà de la fin du métrage.",
            "guide.curvesMatched": "<b>Où vous en êtes :</b> la préconfiguration sur laquelle se trouve l'éditeur s'allume dans la bibliothèque, que vous l'ayez cliquée, que vous ayez saisi les valeurs ou amené les poignées dessus. La correspondance est exacte, et l'éditeur travaille au centième, la précision même qu'affichent les quatre champs : le nombre du champ est donc bien celui qui est stocké. La courbe sur laquelle vous quittez le panneau est mémorisée et revient à la réouverture.",
            "guide.mainColor": "<b>Couleur :</b> la pastille à côté de Solide ouvre un sélecteur avec champ hex, couleurs récentes et pipette. La pipette prélève n'importe où à l'écran, pas seulement dans le panneau : sous Windows un processus auxiliaire attend votre prochain clic, laissez-lui donc un instant jusqu'à ce que le bouton se mette à pulser avant de cliquer ; sous macOS elle ouvre la fenêtre de couleurs du système, dont la loupe fait la même chose. Cette couleur est aussi utilisée par le script de raccourci du solide coloré.",
            "guide.troubleSize": "<b>Le panneau s'ouvre à une largeur bizarre :</b> dès qu'un panneau a été ancré, After Effects mémorise sa taille dans l'espace de travail et ignore ce que demande l'extension. Impossible d'y remédier depuis l'extension. Dimensionnez-le comme vous voulez, puis Fenêtre &gt; Espace de travail &gt; Enregistrer les modifications de cet espace de travail, et quittez After Effects par Fichier &gt; Quitter pour que les préférences soient écrites. Revenir plus tard à cet espace de travail restaure la disposition. Le panneau, lui, est conçu pour fonctionner à n'importe quelle largeur, jusqu'à un ancrage étroit.",
            "main.transformValues": "Valeurs de transformation",
            "main.tfAnchor": "Ancrage",
            "main.tfPosition": "Position",
            "main.tfScale": "Échelle",
            "main.tfRotation": "Rotation",
            "main.tfOpacity": "Opacité",
            "main.transformAbout": "Faites glisser une valeur latéralement pour la modifier, ou cliquez dessus pour la saisir. Maj élargit le pas, Ctrl l'affine. Les lignes suivent la sélection d'elles-mêmes, et seule la valeur que vous changez est écrite : le reste du calque est préservé même avec plusieurs calques sélectionnés. La chaîne conserve les proportions de l'échelle. Une propriété avec images clés s'écrit comme dans la timeline : sur une image clé elle la met à jour, entre deux elle en crée une. Seule une ligne pilotée par une expression est grisée, puisque c'est l'expression qui décide de la valeur. Un calque 3D conserve son Z.",
            "main.shapes": "Calques de forme",
            "main.shapeFill": "Fond",
            "main.shapeStroke": "Contour",
            "main.shapeWidth": "Épaisseur",
            "main.shapesAbout": "Les lignes montrent ce que porte réellement le groupe de forme sélectionné - quel groupe, c'est votre sélection dans la timeline qui le décide. Choisissez une couleur ou faites glisser une valeur et cela s'applique aussitôt ; seul ce que vous touchez est écrit, et une propriété avec images clés en reçoit une comme dans la timeline. Les lignes que la forme n'a pas sont masquées : une ellipse n'a pas d'arrondi.",
            "msg.transformRead": "Lu depuis « {0} »",
            "msg.nothingToApply": "Renseignez au moins une valeur",
