            "ae.exprAdded": "Expression ajoutée sur {0} calques",
            "ae.exprRemoved": "Expression retirée de {0} calques",
            "guide.rowModifiers": "<b>Touches de modification sur les lignes :</b> Maj pendant le glissement d'une valeur multiplie le pas par dix, Ctrl l'affine. Alt+clic sur un chronomètre ajoute ou retire une expression au lieu d'activer l'animation, le même réflexe que dans la timeline. Le travail est confié à After Effects lui-même, via Animation &gt; Ajouter une expression : la ligne d'expression s'ouvre prête à la saisie et le texte est la référence propre de la propriété, exactement comme après un Alt+clic dans la timeline.",
