            "dlg.presetNameDefault": "Il mio predefinito",
            "dlg.restoreDefaultsConfirm": "Riportare tutto il pannello allo stato originale? Verranno eliminate tutte le librerie che hai creato o importato, la cartella dei predefiniti di effetti con i suoi preferiti e la dimensione dell'editor.",
