            "ae.orgEmptyRemoved": "Cartelle vuote rimosse: {0}",
            "ae.cannotMove": "Impossibile spostare: {0}",
            "guide.curvesRamps": "<b>Rampe di velocità:</b> i predefiniti da slowMid a hitOut sono pensati per il Time Remapping. Attivalo su un livello (Livello &gt; Tempo &gt; Abilita rimappatura temporale), seleziona entrambi i fotogrammi chiave e premi Applica. Leggi la curva come un profilo di velocità: la sua pendenza è la velocità di riproduzione, quindi un centro piatto è rallentatore e le estremità ripide sono le parti veloci ai lati. Nessuna supera il bersaglio, perché sul Time Remap significherebbe leggere oltre la fine del filmato.",
            "guide.curvesMatched": "<b>Dove ti trovi:</b> il predefinito su cui si trova l'editor si illumina nella libreria, che tu ci abbia cliccato sopra, abbia digitato i valori o ci abbia trascinato le maniglie. La corrispondenza è esatta e l'editor lavora in centesimi, la stessa precisione mostrata dai quattro campi, quindi il numero nel campo è davvero quello memorizzato. La curva su cui lasci il pannello viene ricordata e torna alla riapertura.",
            "guide.mainColor": "<b>Colore:</b> il campione accanto a Solido apre un selettore con campo hex, colori recenti e contagocce. Il contagocce preleva da qualsiasi punto dello schermo, non solo dentro il pannello: su Windows un processo di supporto attende il tuo prossimo clic, quindi dagli un momento finché il pulsante non inizia a pulsare e solo allora fai clic; su macOS si apre il pannello colori di sistema, la cui lente fa lo stesso. Questo colore è usato anche dallo script scorciatoia per il solido colorato.",
            "guide.troubleSize": "<b>Il pannello si apre a una larghezza strana:</b> una volta che un pannello è stato agganciato, After Effects ne ricorda la dimensione nell'area di lavoro e ignora ciò che l'estensione chiede. Dall'estensione non c'è modo di aggirarlo. Dimensionalo come preferisci, poi Finestra &gt; Area di lavoro &gt; Salva modifiche a questa area di lavoro, ed esci da After Effects con File &gt; Esci perché le preferenze vengano scritte. Tornare più tardi a quell'area di lavoro ripristina la disposizione. Il pannello è comunque costruito per funzionare a qualsiasi larghezza, anche in un aggancio stretto.",
            "main.transformValues": "Valori di trasformazione",
            "main.tfAnchor": "Ancoraggio",
            "main.tfPosition": "Posizione",
            "main.tfScale": "Scala",
            "main.tfRotation": "Rotazione",
            "main.tfOpacity": "Opacità",
            "main.transformAbout": "Trascina un valore lateralmente per regolarlo, o fai clic per digitarlo. Maiusc rende il trascinamento più grossolano, Ctrl più fine. Le righe seguono la selezione da sole e viene scritto solo il valore che cambi, quindi il resto del livello resta intatto anche con più livelli selezionati. La catena mantiene le proporzioni della scala. Una proprietà con fotogrammi chiave viene scritta come nella timeline: sopra un fotogramma chiave lo aggiorna, tra due ne crea uno nuovo. È attenuata solo una riga guidata da un'espressione, perché è l'espressione a decidere il valore. Un livello 3D conserva la sua Z.",
            "main.shapes": "Livelli forma",
            "main.shapeFill": "Riempimento",
            "main.shapeStroke": "Traccia",
            "main.shapeWidth": "Spessore",
            "main.shapesAbout": "Le righe mostrano ciò che il gruppo forma selezionato ha davvero - quale gruppo lo decide ciò che hai selezionato nella timeline. Scegli un colore o trascina un valore e viene applicato subito; viene scritto solo ciò che tocchi, e una proprietà con fotogrammi chiave ne riceve uno come nella timeline. Le righe che la forma non ha vengono nascoste: un'ellisse non ha arrotondamento.",
            "msg.transformRead": "Letto da '{0}'",
            "msg.nothingToApply": "Inserisci almeno un valore",
