            "guide.rowModifiers": "<b>Tasti modificatori sulle righe:</b> Maiusc mentre trascini un valore rende il passo dieci volte più grosso, Ctrl lo affina. Alt+clic su un cronometro aggiunge o toglie un'espressione invece di attivare l'animazione, lo stesso riflesso della timeline. Il lavoro viene affidato ad After Effects stesso, tramite Animazione &gt; Aggiungi espressione, così la riga dell'espressione si apre pronta per la scrittura e il testo è il riferimento proprio della proprietà, esattamente come dopo un Alt+clic nella timeline.",
