            "ae.orgEmptyRemoved": "Pastas vazias removidas: {0}",
            "ae.cannotMove": "Não é possível mover: {0}",
            "guide.curvesRamps": "<b>Rampas de velocidade:</b> as predefinições de slowMid até hitOut foram feitas para o Time Remapping. Ative-o numa camada (Camada &gt; Tempo &gt; Ativar remapeamento de tempo), selecione os dois quadros-chave e clique em Aplicar. Leia a curva como um perfil de velocidade: a inclinação é a taxa de reprodução, então um meio plano é câmera lenta e as pontas íngremes são os trechos rápidos de cada lado. Nenhuma ultrapassa, porque no Time Remap isso significaria ler além do fim do material.",
            "guide.curvesMatched": "<b>Onde você está:</b> a predefinição em que o editor está acende na biblioteca, seja porque você clicou nela, digitou os valores ou arrastou as alças até ela. A correspondência é exata e o editor trabalha em centésimos, a mesma precisão que os quatro campos mostram, então o número no campo é de fato o que está guardado. A curva em que você deixa o painel é lembrada e volta ao reabrir.",
            "guide.mainColor": "<b>Cor:</b> a amostra ao lado de Sólido abre um seletor com campo hex, cores recentes e conta-gotas. O conta-gotas captura de qualquer ponto da tela, não só dentro do painel: no Windows um processo auxiliar espera pelo seu próximo clique, então dê um instante até o botão começar a pulsar e só então clique; no macOS abre o painel de cores do sistema, cuja lupa faz o mesmo. Essa cor também é usada pelo script de atalho do sólido colorido.",
            "guide.troubleSize": "<b>O painel abre numa largura estranha:</b> depois que um painel é encaixado, o After Effects lembra o tamanho dele no espaço de trabalho e ignora o que a extensão pede. De dentro da extensão não há como contornar isso. Ajuste como quiser, então Janela &gt; Espaço de trabalho &gt; Salvar alterações neste espaço de trabalho, e feche o After Effects por Arquivo &gt; Sair para que as preferências sejam gravadas. Voltar depois para esse espaço de trabalho restaura o layout. O painel em si foi feito para funcionar em qualquer largura, até num encaixe estreito.",
            "main.transformValues": "Valores de transformação",
            "main.tfAnchor": "Ancoragem",
            "main.tfPosition": "Posição",
            "main.tfScale": "Escala",
            "main.tfRotation": "Rotação",
            "main.tfOpacity": "Opacidade",
            "main.transformAbout": "Arraste um valor para o lado para ajustá-lo, ou clique para digitar. Shift engrossa o arraste, Ctrl refina. As linhas acompanham a seleção sozinhas e só o valor que você muda é gravado, então o resto da camada fica intocado mesmo com várias camadas selecionadas. A corrente mantém a escala proporcional. Uma propriedade com quadros-chave é gravada como na linha do tempo: sobre um quadro-chave atualiza aquele, entre eles cria um novo. Só fica esmaecida uma linha com expressão, porque é ela que decide o valor. Uma camada 3D mantém o seu Z.",
            "main.shapes": "Camadas de forma",
            "main.shapeFill": "Preenchimento",
            "main.shapeStroke": "Traçado",
            "main.shapeWidth": "Espessura",
            "main.shapesAbout": "As linhas mostram o que o grupo de forma selecionado realmente tem - e qual grupo é decidido pelo que você tem selecionado na linha do tempo. Escolha uma cor ou arraste um valor e vale na hora; só o que você toca é gravado, e uma propriedade com quadros-chave ganha um como na linha do tempo. Linhas que a forma não tem ficam ocultas: uma elipse não tem arredondamento.",
