            "guide.rowModifiers": "<b>Teclas modificadoras nas linhas:</b> Shift ao arrastar um valor engrossa o passo dez vezes, Ctrl refina. Alt+clique num cronômetro adiciona ou remove uma expressão em vez de ligar a animação, o mesmo reflexo da linha do tempo. O trabalho fica com o próprio After Effects, via Animação &gt; Adicionar expressão, então a linha da expressão abre pronta para digitar e o texto é a referência da própria propriedade, igual ao que um Alt+clique na linha do tempo deixaria.",
