            "org.note": "Композиции, использованные внутри других, попадают в Precomps. Пустые папки удаляются.",
            "org.fullAbout": "Раскладывает все элементы по папкам согласно типу:<br /><b>Assets</b> · <b>Audio</b> · <b>Comps</b> · <b>Footage</b> · <b>Precomps</b> · <b>Solids</b><br />Композиции, использованные внутри других, попадают в Precomps. Пустые папки удаляются.",
            "org.run": "Упорядочить проект",
            "org.working": "Упорядочивание проекта...",
            "settings.language": "Язык",
            "settings.languageAbout": "Действует на всю панель, включая сообщения.",
            "settings.langNote": "Переводы, кроме английского и чешского, сделаны машинно и могут содержать ошибки, особенно в Руководстве. Если что-то читается странно, переключитесь на английский — это исходный текст.",
            "settings.about": "О панели",
            "settings.aboutText": "BeneG Toolkit — редактор кривых плавности с поддержкой формата .flow, библиотекой пресетов и инструментами упорядочивания проекта.",
