            "ae.orgEmptyRemoved": "Удалено пустых папок: {0}",
            "ae.cannotMove": "Не удаётся переместить: {0}",
            "guide.curvesRamps": "<b>Speed ramp:</b> пресеты от slowMid до hitOut рассчитаны на Time Remapping. Включите его на слое (Layer &gt; Time &gt; Enable Time Remapping), выделите оба ключевых кадра и нажмите Применить. Читайте кривую как профиль скорости: её наклон — это скорость воспроизведения, так что плоская середина означает замедление, а крутые концы — быстрые участки по краям. Ни одна из них не даёт перелёта, потому что на Time Remap это означало бы чтение за концом материала.",
            "guide.curvesMatched": "<b>Где вы сейчас:</b> пресет, на котором стоит редактор, подсвечивается в библиотеке — независимо от того, щёлкнули вы по нему, вписали значения или подтянули к нему манипуляторы. Совпадение точное, а редактор работает в сотых, ровно с той точностью, которую показывают четыре поля. Число в поле — это действительно то, что хранится. Кривая, на которой вы закрываете панель, запоминается и возвращается при следующем открытии.",
            "guide.mainColor": "<b>Цвет:</b> образец рядом с Solid открывает пипетку с полем hex, недавними цветами и пробником экрана. Пробник берёт цвет в любой точке экрана, а не только внутри панели: в Windows вспомогательный процесс ждёт вашего следующего щелчка, поэтому дайте ему мгновение, пока кнопка не начнёт пульсировать, и только потом щёлкайте; в macOS открывается системная палитра, лупа которой делает то же самое. Этот цвет использует и скрипт горячей клавиши для цветного солида.",
            "guide.troubleSize": "<b>Панель открывается со странной шириной:</b> как только панель была пристыкована, After Effects запоминает её размер в рабочей среде и игнорирует то, что просит расширение. Изнутри расширения обойти это невозможно. Задайте нужный размер, затем Window &gt; Workspace &gt; Save Changes to This Workspace, и завершите After Effects через File &gt; Exit, чтобы настройки записались. Возврат к этой рабочей среде позже восстановит раскладку. Сама панель рассчитана на любую ширину, вплоть до узкого дока.",
            "main.transformValues": "Значения трансформации",
            "main.tfAnchor": "Привязка",
            "main.tfPosition": "Позиция",
            "main.tfScale": "Масштаб",
            "main.tfRotation": "Поворот",
            "main.tfOpacity": "Непрозрачность",
            "main.transformAbout": "Тяните значение вбок, чтобы прокрутить его, или щёлкните, чтобы вписать. Shift огрубляет шаг, Ctrl уточняет. Строки сами следуют за выделением, и записывается только то значение, которое вы меняете, поэтому остальное на слое остаётся нетронутым даже при нескольких выделенных слоях. Цепочка сохраняет пропорции масштаба. Свойство с ключевыми кадрами записывается так же, как на таймлайне: на ключевом кадре он обновляется, между ними появляется новый. Приглушена только строка с выражением, потому что значение определяет оно. У 3D-слоя сохраняется его Z.",
            "main.shapes": "Shape-слои",
            "main.shapeFill": "Заливка",
            "main.shapeStroke": "Обводка",
            "main.shapeWidth": "Толщина",
            "main.shapesAbout": "Строки показывают, что на самом деле есть у выделенной группы фигуры — а какая это группа, решает выделение на таймлайне. Выберите цвет или потяните значение — применится сразу; записывается только то, к чему вы прикоснулись, а свойство с ключевыми кадрами получит ключ так же, как на таймлайне. Строки, которых у фигуры нет, скрыты: у эллипса нет скругления.",
