            "guide.rowModifiers": "<b>Модификаторы на строках:</b> Shift при перетаскивании значения делает шаг в десять раз крупнее, Ctrl — точнее. Alt+щелчок по секундомеру добавляет или удаляет выражение вместо включения анимации — тот же рефлекс, что и на таймлайне. Работу берёт на себя сам After Effects через Animation &gt; Add Expression, поэтому строка выражения открывается готовой к набору, а текстом становится собственная ссылка свойства — ровно так, как оставил бы Alt+щелчок на таймлайне.",
