            "settings.langNote": "अंग्रेज़ी और चेक के अलावा बाकी अनुवाद मशीन की मदद से बनाए गए हैं और उनमें गलतियाँ हो सकती हैं, खासकर गाइड में। अगर कुछ अटपटा लगे तो अंग्रेज़ी पर स्विच करें — वही मूल पाठ है।",
