            "msg.exportCancelled": "एक्सपोर्ट रद्द किया गया",
            "msg.exported": ".flow में एक्सपोर्ट हो गया",
            "dlg.newLibName": "नई लाइब्रेरी का नाम:",
            "dlg.newLibDefault": "नई लाइब्रेरी",
            "dlg.renameLibName": "लाइब्रेरी का नया नाम:",
