            "guide.curvesRamps": "<b>Speed ramp:</b> slowMid से hitOut तक के प्रीसेट Time Remapping के लिए हैं। इसे layer पर चालू करें (Layer &gt; Time &gt; Enable Time Remapping), दोनों keyframes चुनें और लागू करें दबाएँ। कर्व को रफ़्तार के प्रोफ़ाइल की तरह पढ़ें: उसकी ढलान ही playback की गति है, इसलिए सपाट मध्य का मतलब slow motion और तीखे सिरों का मतलब उसके दोनों ओर के तेज़ हिस्से। इनमें से कोई overshoot नहीं करता, क्योंकि time remap में इसका अर्थ footage के अंत से आगे पढ़ना होता।",
            "guide.curvesMatched": "<b>आप कहाँ हैं:</b> एडिटर जिस प्रीसेट पर है, वह लाइब्रेरी में जल उठता है — चाहे आपने उस पर क्लिक किया हो, मान टाइप किए हों, या handles खींचकर वहाँ पहुँचाए हों। मिलान सटीक है, और एडिटर सैकड़वें भाग में काम करता है, यानी उतनी ही परिशुद्धता जितनी वे चार फ़ील्ड दिखाते हैं। इसलिए फ़ील्ड में दिखने वाला अंक वही है जो सहेजा गया है। जिस कर्व पर आप पैनल छोड़ते हैं, वह याद रखा जाता है और अगली बार खोलने पर लौट आता है।",
            "guide.mainColor": "<b>रंग:</b> Solid के बगल का रंग-खाना एक picker खोलता है जिसमें hex फ़ील्ड, हाल के रंग और एक पिपेट होता है। पिपेट स्क्रीन पर कहीं से भी रंग उठाता है, केवल पैनल के भीतर से नहीं — Windows पर एक सहायक प्रक्रिया आपके अगले क्लिक की प्रतीक्षा करती है, इसलिए बटन के धड़कने शुरू होने तक थोड़ा रुकें और तभी क्लिक करें; macOS पर सिस्टम का रंग पैनल खुलता है, जिसका आवर्धक यही काम करता है। यही रंग रंगीन solid वाली शॉर्टकट स्क्रिप्ट भी इस्तेमाल करती है।",
            "guide.troubleSize": "<b>पैनल अजीब चौड़ाई में खुलता है:</b> एक बार पैनल dock हो जाने के बाद After Effects उसका आकार workspace में याद रखता है और extension जो माँगता है उसे अनदेखा कर देता है। extension के भीतर से इसका कोई उपाय नहीं है। जैसा चाहिए वैसा आकार दें, फिर Window &gt; Workspace &gt; Save Changes to This Workspace करें, और After Effects को File &gt; Exit से बंद करें ताकि preferences लिखी जाएँ। बाद में उसी workspace पर लौटने से layout वापस आ जाता है। पैनल स्वयं किसी भी चौड़ाई पर काम करने के लिए बना है, सँकरे dock पर भी।",
            "main.transformValues": "Transform के मान",
            "main.tfAnchor": "Anchor",
            "main.tfPosition": "Position",
            "main.tfScale": "Scale",
            "main.tfRotation": "Rotation",
            "main.tfOpacity": "Opacity",
            "main.transformAbout": "किसी मान को बगल में खींचकर scrub करें, या क्लिक करके टाइप करें। Shift खिंचाव को मोटा करता है, Ctrl बारीक। पंक्तियाँ स्वयं चयन का अनुसरण करती हैं, और केवल वही मान लिखा जाता है जिसे आप बदलते हैं, इसलिए कई layers चुनी होने पर भी बाकी layer अछूती रहती है। ज़ंजीर Scale को अनुपात में रखती है। जिस property पर keyframes हैं, उसमें timeline की तरह लिखा जाता है: keyframe पर हों तो वही बदलता है, बीच में हों तो नया बन जाता है। धुँधली केवल वह पंक्ति होती है जिस पर expression है, क्योंकि मान वही तय करता है। 3D layer का Z बना रहता है।",
            "main.shapes": "Shape layers",
            "main.shapeFill": "Fill",
            "main.shapeStroke": "Stroke",
            "main.shapeWidth": "चौड़ाई",
            "main.shapesAbout": "पंक्तियाँ दिखाती हैं कि चुनी हुई shape group पर वास्तव में क्या है — और कौन सी group, यह timeline में आपके चयन से तय होता है। रंग चुनें या मान खींचें, असर तुरंत होता है; केवल वही लिखा जाता है जिसे आपने छुआ, और जिस property पर keyframes हैं उस पर timeline की तरह keyframe बन जाता है। जो पंक्तियाँ उस shape पर नहीं हैं, वे छिपी रहती हैं: ellipse पर roundness नहीं होता।",
