            "ae.cannotMove": "移動できません: {0}",
            "guide.curvesRamps": "<b>スピードランプ:</b> slowMid から hitOut までのプリセットはタイムリマップ用です。レイヤーで有効にし（レイヤー &gt; 時間 &gt; 時間リマップを使用可能にする）、両方のキーフレームを選んで適用を押します。カーブは速度のプロファイルとして読んでください。傾きが再生速度なので、中央が平らならスローモーション、両端が急ならその前後が速い部分です。どれもオーバーシュートしません。タイムリマップでそれをするとフッテージの終わりより先を読むことになるためです。",
            "guide.curvesMatched": "<b>いまどこにいるか:</b> エディターが乗っているプリセットは、クリックしたか、値を入力したか、ハンドルをそこまでドラッグしたかにかかわらず、ライブラリで光ります。一致は厳密で、エディターは 4 つの数値欄と同じ 100 分の 1 の精度で動きます。つまり欄に見えている数値が、そのまま保持されている数値です。パネルを閉じたときのカーブは記憶され、次に開くと戻ってきます。",
            "guide.mainColor": "<b>色:</b> 平面の隣の色見本を押すと、hex 欄、最近使った色、スポイトのあるピッカーが開きます。スポイトはパネル内だけでなく画面のどこからでも色を取れます。Windows では補助プロセスが次のクリックを待つので、ボタンが点滅し始めるまで少し待ってからクリックしてください。macOS ではシステムのカラーパネルが開き、その拡大鏡が同じ役割を果たします。この色はカラー平面用のショートカットスクリプトでも使われます。",
            "guide.troubleSize": "<b>パネルが妙な幅で開く場合:</b> 一度ドッキングしたパネルのサイズは After Effects がワークスペースに記憶し、拡張機能側の指定を無視します。拡張機能の中からはどうにもなりません。好みのサイズに整えてから ウィンドウ &gt; ワークスペース &gt; このワークスペースへの変更を保存 を実行し、環境設定が書き込まれるよう ファイル &gt; 終了 で After Effects を終了してください。後でそのワークスペースに切り替えればレイアウトが戻ります。パネル自体はどんな幅でも、狭いドックでも動くように作られています。",
            "main.transformValues": "トランスフォームの値",
            "main.tfAnchor": "アンカー",
            "main.tfPosition": "位置",
            "main.tfScale": "スケール",
            "main.tfRotation": "回転",
            "main.tfOpacity": "不透明度",
            "main.transformAbout": "値を横にドラッグするとスクラブでき、クリックすると入力できます。Shift で粗く、Ctrl で細かく動きます。行は自分で選択に追随し、書き込まれるのは変更した値だけなので、複数レイヤーを選んでいてもそれ以外はそのままです。鎖はスケールの比率を保ちます。キーフレームのあるプロパティにはタイムラインと同じように書き込まれます。キーフレーム上ならそれを更新し、間にいれば新しく打たれます。淡く表示されるのはエクスプレッションの行だけで、値を決めているのがそちらだからです。3D レイヤーの Z はそのまま残ります。",
            "main.shapes": "シェイプレイヤー",
