            "main.shapeWidth": "幅",
            "main.shapesAbout": "各行は選択中のシェイプグループが実際に持っている値を示します。どのグループかはタイムラインでの選択が決めます。色を選ぶか値をドラッグすればすぐに反映され、触れたものだけが書き込まれます。キーフレームのあるプロパティには、タイムラインと同じようにキーフレームが打たれます。そのシェイプにない行は隠れます。楕円に角丸はありません。",
