            "ae.orgEmptyRemoved": "제거한 빈 폴더: {0}",
            "ae.cannotMove": "이동할 수 없습니다: {0}",
            "guide.curvesRamps": "<b>속도 램프:</b> slowMid 부터 hitOut 까지의 사전 설정은 시간 다시 매핑용입니다. 레이어에서 켜고 (레이어 &gt; 시간 &gt; 시간 다시 매핑 사용), 두 키프레임을 모두 선택한 뒤 적용을 누르세요. 커브는 속도 프로파일로 읽습니다. 기울기가 재생 속도이므로 가운데가 평평하면 슬로 모션이고, 양 끝이 가파르면 그 바깥쪽이 빠른 구간입니다. 어느 것도 오버슛하지 않는데, 시간 다시 매핑에서는 그것이 푸티지 끝을 넘어 읽는다는 뜻이기 때문입니다.",
            "guide.curvesMatched": "<b>지금 어디에 있는지:</b> 편집기가 올라가 있는 사전 설정은 라이브러리에서 불이 들어옵니다. 클릭했든, 값을 입력했든, 핸들을 끌어다 맞췄든 마찬가지입니다. 일치는 정확하며, 편집기는 네 개의 입력란이 보여 주는 것과 같은 100 분의 1 단위로 동작합니다. 즉 칸에 보이는 숫자가 실제로 저장된 숫자입니다. 패널을 떠날 때의 커브는 기억되어 다시 열면 돌아옵니다.",
            "guide.mainColor": "<b>색상:</b> 단색 옆의 색상 견본을 누르면 hex 입력란, 최근 색상, 스포이트가 있는 선택기가 열립니다. 스포이트는 패널 안뿐 아니라 화면 어디서든 색을 집습니다. Windows 에서는 보조 프로세스가 다음 클릭을 기다리므로, 버튼이 깜빡이기 시작할 때까지 잠시 기다렸다가 클릭하세요. macOS 에서는 시스템 색상 패널이 열리며 그 돋보기가 같은 일을 합니다. 이 색상은 컬러 단색용 단축키 스크립트에서도 쓰입니다.",
            "guide.troubleSize": "<b>패널이 이상한 너비로 열릴 때:</b> 패널을 한 번 도킹하고 나면 After Effects 가 그 크기를 작업 영역에 기억하고 확장 기능이 요청하는 값은 무시합니다. 확장 기능 안에서는 이를 우회할 방법이 없습니다. 원하는 크기로 맞춘 뒤 창 &gt; 작업 영역 &gt; 이 작업 영역에 대한 변경 사항 저장 을 실행하고, 환경 설정이 기록되도록 파일 &gt; 종료 로 After Effects 를 닫으세요. 나중에 그 작업 영역으로 전환하면 배치가 복원됩니다. 패널 자체는 좁은 도킹을 포함해 어떤 너비에서도 동작하도록 만들어졌습니다.",
            "main.transformValues": "변형 값",
            "main.tfAnchor": "앵커",
            "main.tfPosition": "위치",
            "main.tfScale": "크기",
            "main.tfRotation": "회전",
            "main.tfOpacity": "불투명도",
            "main.transformAbout": "값을 옆으로 끌면 스크럽되고, 클릭하면 입력할 수 있습니다. Shift 는 크게, Ctrl 은 잘게 움직입니다. 행은 스스로 선택을 따라가며, 기록되는 것은 바꾼 값뿐이라 여러 레이어를 선택했어도 나머지는 그대로 남습니다. 사슬은 크기 비율을 유지합니다. 키프레임이 있는 속성은 타임라인과 같은 방식으로 기록됩니다. 키프레임 위라면 그것을 갱신하고, 사이라면 새로 하나가 생깁니다. 흐리게 표시되는 것은 표현식이 걸린 행뿐인데, 값을 정하는 것이 표현식이기 때문입니다. 3D 레이어는 Z 를 유지합니다.",
            "main.shapes": "셰이프 레이어",
            "main.shapeFill": "칠",
            "main.shapeStroke": "선",
            "main.shapeWidth": "두께",
            "main.shapesAbout": "각 행은 선택한 셰이프 그룹이 실제로 가진 값을 보여 줍니다. 어느 그룹인지는 타임라인의 선택이 정합니다. 색을 고르거나 값을 끌면 바로 반영되고, 손댄 것만 기록되며, 키프레임이 있는 속성에는 타임라인과 마찬가지로 키프레임이 찍힙니다. 그 셰이프에 없는 행은 숨겨집니다. 타원에는 둥글기가 없습니다.",
            "msg.transformRead": "'{0}' 에서 읽었습니다",
