            "ae.orgEmptyRemoved": "已移除空文件夹：{0}",
            "ae.cannotMove": "无法移动：{0}",
            "guide.curvesRamps": "<b>速度曲线：</b>从 slowMid 到 hitOut 的预设是为时间重映射准备的。在图层上启用它（图层 &gt; 时间 &gt; 启用时间重映射），选中两个关键帧后按应用。把曲线当作速度剖面来读：斜率就是播放速度，所以中段平坦意味着慢动作，两端陡峭则是它前后的快速部分。这些曲线都不会过冲，因为在时间重映射上那意味着读到素材的结尾之外。",
            "guide.curvesMatched": "<b>你现在在哪：</b>编辑器当前所处的那个预设会在库中亮起，无论你是点击了它、输入了数值，还是把手柄拖到了那里。匹配是精确的，编辑器以百分之一为单位工作，正是那四个输入框所显示的精度，所以框里的数字就是实际保存的数字。你离开面板时所停留的曲线会被记住，下次打开时回到原处。",
            "guide.mainColor": "<b>颜色：</b>纯色旁边的色块会打开一个拾色器，带有 hex 输入框、最近使用的颜色和吸管。吸管可以在屏幕任意位置取色，不限于面板内部：在 Windows 上会有一个辅助进程等待你的下一次点击，所以请稍等到按钮开始闪动再点；在 macOS 上会打开系统调色板，用它的放大镜完成同样的事。彩色纯色的快捷键脚本也使用这个颜色。",
            "guide.troubleSize": "<b>面板打开时宽度不对：</b>面板一旦被停靠过，After Effects 就会把它的尺寸记在工作区里，并忽略扩展所请求的值。从扩展内部无法绕开这一点。把它调成你想要的大小，然后执行 窗口 &gt; 工作区 &gt; 将更改保存到此工作区，再通过 文件 &gt; 退出 关闭 After Effects，让首选项被写入。以后切换回该工作区就会恢复布局。面板本身是按任意宽度都能正常工作来做的，窄停靠也一样。",
            "main.transformValues": "变换数值",
            "main.tfAnchor": "锚点",
            "main.tfPosition": "位置",
            "main.tfScale": "缩放",
            "main.tfRotation": "旋转",
            "main.tfOpacity": "不透明度",
            "main.transformAbout": "横向拖动数值即可擦洗，点击则可输入。Shift 让拖动更粗，Ctrl 更细。这些行会自行跟随选择，只有你改动的那个值会被写入，所以即使选中多个图层，其余部分也不会被动到。链条保持缩放比例。带关键帧的属性会按时间轴的方式写入：正好在关键帧上就更新它，在两帧之间则新建一个。只有带表达式的行会变灰，因为决定数值的是表达式。3D 图层的 Z 保持不变。",
            "main.shapes": "形状图层",
