            "main.shapeWidth": "宽度",
            "main.shapesAbout": "这些行显示选中的形状组实际带有的值，具体是哪个组由你在时间轴上的选择决定。选一个颜色或拖动数值就会立刻生效，只有你碰过的才会被写入；带关键帧的属性会像在时间轴上那样打上关键帧。该形状没有的行会被隐藏：椭圆没有圆度。",
