            "org.fullAbout": "Roztřídí všechny položky do složek podle typu:<br /><b>Assets</b> · <b>Audio</b> · <b>Comps</b> · <b>Footage</b> · <b>Precomps</b> · <b>Solids</b><br />Kompozice použité uvnitř jiných jdou do Precomps. Prázdné složky se smažou.",
