            "upd.scriptsAbout": "Scripty pro klávesové zkratky musí ležet ve Scripts složce After Effects, ne v panelu. Tohle je tam nakopíruje pro každou nainstalovanou verzi AE — bez práv správce. Další aktualizace je pak už udržují samy.",
