            "ae.cannotMove": "Nelze přesunout: {0}",
            "guide.curvesRamps": "<b>Speed rampy:</b> presety od slowMid po hitOut jsou určené pro Time Remapping. Zapni ho na vrstvě (Layer &gt; Time &gt; Enable Time Remapping), označ oba klíče a dej Aplikovat. Křivku čti jako rychlostní profil: její sklon je rychlost přehrávání, takže plochý střed je zpomalení a strmé konce jsou rychlé části kolem něj. Žádná z nich nepřestřeluje, protože u time remapu by to znamenalo čtení za koncem stopáže.",
            "guide.curvesMatched": "<b>Kde právě jsi:</b> preset, na kterém editor stojí, se v knihovně rozsvítí — ať už jsi na něj klikl, napsal hodnoty nebo na něj dotáhl úchyty. Shoda je přesná a editor pracuje v setinách, tedy ve stejné přesnosti, jakou ukazují ta čtyři pole. Číslo v poli je tedy skutečně to, co je uložené. Křivku, na které panel opustíš, si pamatuje a po dalším otevření se vrátí.",
            "guide.mainColor": "<b>Barva:</b> políčko vedle Solidu otevře picker s hex polem, posledními barvami a pipetou. Pipeta nabírá kdekoliv na obrazovce, ne jen uvnitř panelu — na Windows čeká pomocný proces na tvoje další kliknutí, takže mu dej chvilku, než tlačítko začne pulzovat, a teprve pak klikni; na macOS se otevře systémový barevný panel, jehož lupa dělá totéž. Tuhle barvu používá i zkratkový skript pro barevný solid.",
            "guide.troubleSize": "<b>Panel se otevře v divné šířce:</b> jakmile je panel jednou ukotvený, After Effects si jeho velikost pamatuje ve workspace a ignoruje, co si rozšíření žádá. Z rozšíření se s tím nedá nic udělat. Nastav si ho, jak chceš, pak Window &gt; Workspace &gt; Save Changes to This Workspace, a ukonči After Effects přes File &gt; Exit, aby se preference zapsaly. Pozdější přepnutí zpátky na ten workspace layout obnoví. Panel sám je stavěný na libovolnou šířku, i na úzký dok.",
            "main.transformValues": "Hodnoty transformace",
            "main.tfAnchor": "Kotva",
            "main.tfPosition": "Pozice",
            "main.tfScale": "Měřítko",
            "main.tfRotation": "Rotace",
            "main.tfOpacity": "Krytí",
            "main.transformAbout": "Hodnotu scrubuješ tažením do stran, kliknutím do ní píšeš. Shift tažení zhrubí, Ctrl zjemní. Řádky sledují výběr samy a zapíše se jen hodnota, kterou změníš, takže zbytek vrstvy zůstane nedotčený i při více vybraných vrstvách. Řetízek drží měřítko v poměru. Do animované vlastnosti se zapisuje stejně jako v timeline: stojíš-li na klíči, přepíše se, mezi klíči vznikne nový. Zašedlý je jen řádek s expressionem, protože o hodnotě rozhoduje ten. 3D vrstvě zůstává její Z.",
            "main.shapes": "Shape vrstvy",
            "main.shapeFill": "Výplň",
            "main.shapeStroke": "Obrys",
            "main.shapeWidth": "Šířka",
            "main.shapesAbout": "Řádky ukazují, co vybraná skupina tvaru skutečně má — a kterou skupinu, to určuje výběr v timeline. Vyber barvu nebo přetáhni hodnotu a projeví se to hned; zapíše se jen to, čeho se dotkneš, a u animované vlastnosti vznikne klíč stejně jako v timeline. Řádky, které tvar nemá, jsou skryté: elipsa zaoblení nemá.",
