            "guide.rowModifiers": "<b>Modifikátory na řádcích:</b> Shift při tažení hodnoty zhrubí krok desetkrát, Ctrl ho zjemní. Alt+klik na stopky přidá nebo odebere expression místo zapnutí animace — stejný reflex jako v timeline. Práci přenechá samotnému AE přes Animation &gt; Add Expression, takže se řádek s expressionem otevře připravený k psaní a text je vlastní odkaz té vlastnosti, přesně jak by ho nechal Alt+klik v timeline.",
